#include <stdio.h>

#define MAXN 200005

static long long bitA[MAXN], bitB[MAXN];
static int N;

static inline void add(long long *bit, int idx, long long val) {
    while (idx <= N) {
        bit[idx] += val;
        idx += idx & -idx;
    }
}

static inline long long sum(const long long *bit, int idx) {
    long long res = 0;
    while (idx > 0) {
        res += bit[idx];
        idx -= idx & -idx;
    }
    return res;
}

static inline void range_add(int l, int r, long long a, long long b) {
    add(bitA, l, a);
    add(bitA, r + 1, -a);
    add(bitB, l, b);
    add(bitB, r + 1, -b);
}

static inline long long query(int p) {
    return sum(bitA, p) * (long long)p + sum(bitB, p);
}

int main(void) {
    int M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    for (int k = 0; k < M; ++k) {
        int type, i, v;
        scanf("%d", &type);

        if (type == 3) {
            scanf("%d", &i);
            printf("%lld\n", query(i));
        } else {
            scanf("%d %d", &i, &v);

            if (type == 1) {
                int l = i;
                int r = i + v - 1;
                if (r > N) r = N;
                range_add(l, r, -1, (long long)v + i);
            } else {
                int l = i - v + 1;
                if (l < 1) l = 1;
                int r = i;
                range_add(l, r, 1, (long long)v - i);
            }
        }
    }

    return 0;
}
